"use strict";
(()=>{const L=window.Lab;if(!L||!L.$('engineering-lab'))return;L.init(['case'],()=>{const c=L.$('case').value;let tool,answer,why,series,opts={};if(c==='switch-rlc'){tool='二階初值問題／拉氏';answer='vC(1 s) = '+L.fmt(1+L.homogeneous(2,-1,0,1).x)+' V';series=[{fn:t=>1+L.homogeneous(2,-1,0,t).x}];opts={yMin:0,yMax:1.5,yLabel:'開關後電容電壓（V）'};why='開關剛閉合，要追整段暫態。先交 vC(0)=0 V、iL(0)=0 A 兩張卡，並寫 LC vC″+RC vC′+vC=1 V。相量只保留同頻穩態，不能還原這段起跑。';}else if(c==='sinusoid-rc'){tool='峰值相量';answer='0.707 V ∠−45°';series=[{fn:t=>Math.cos(t),color:'#172a45',dash:'6 5'},{fn:t=>Math.cos(t-Math.PI/4)/Math.sqrt(2)}];opts={xMax:4*Math.PI,yMin:-1.1,yMax:1.1,xLabel:'時間 t（ms）',yLabel:'同頻穩態電壓（V）'};why='ω=1000 rad/s、R=1 kΩ、C=1 μF；已等待暫態衰減，只問振幅與相位。H(jω)=1/(1+jωRC) 可直接得到結果；若重新問接通瞬間，必須回到初值問題。';}else if(c==='pulse'){tool='摺積與傅立葉轉換';answer='y(2 s) = 0.233';series=[{fn:t=>t<=1?1-Math.exp(-t):Math.exp(-(t-1))-Math.exp(-t)}];opts={xMax:4,yMin:0,yMax:1,yLabel:'單次持續輸入的輸出 y（無量綱）'};why='輸入是從 0 到 1 s 的單次矩形，系統 h(t)=e^(−t/(1 s))。摺積算各次貢獻的尾巴，傅立葉轉換看連續頻率內容；不能假裝這個單次事件本來就每秒重複。';}else if(c==='field'){tool='靜電邊值問題';answer='E = −10 V/m';series=[{fn:x=>10*x}];opts={xMax:1,yMin:0,yMax:10,xLabel:'位置 x（m）',yLabel:'電位 V（V）'};why='左端 0 V、右端 10 V、間距 1 m。內部無電荷，V″=0，再用兩端邊界決定 V=(10 V)x/L。這裡沒有開關時間歷程，時間初值不能取代空間邊界。';}else{tool='狀態與二階動態';answer='x(1 s) = '+L.fmt(L.homogeneous(2,1,0,1).x)+' m';series=[{fn:t=>L.homogeneous(2,1,0,t).x}];opts={yMin:-1.5,yMax:1.5,yLabel:'理想彈性機構的位置（m）'};why='已知位置 1 m、速度 0 m/s、m=1 kg、k=4 N/m、b=2 N·s/m。先用兩張狀態卡追蹤放手響應；若之後研究輸入輸出，零初值才可只用轉移函數。真實機器人還有致動器限制與多軸耦合。';}L.plot(L.$('drawing'),series,opts);L.text('result-primary',tool);L.text('result-secondary',answer);L.text('feedback',why);});})();
